const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog,user=null,progress=[],practice=null,view='home';
function local(){try{return JSON.parse(localStorage.getItem('impulso-progress')||'[]')}catch{return []}}
async function api(url,data){const r=await fetch(url,{credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},...(data?{method:'POST',body:JSON.stringify(data)}:{})});let j;try{j=await r.json()}catch{throw Error('No pudimos conectar con el servidor.')}if(!r.ok)throw Error(j.error||'Ocurrió un error.');return j}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
const completed=()=>progress.filter(p=>p.score>=50).length;
const score=id=>progress.find(p=>p.lesson===id)?.score;
const nextLesson=()=>catalog.lessons.find(l=>!(score(l.id)>=50))||catalog.lessons[0];
function nav(id,label,ico){return `<a class="nav ${view===id?'active':''}" href="#${id}" ${view===id?'aria-current="page"':''}><span class="ico" aria-hidden="true">${ico}</span>${label}</a>`}
function frame(content){app.innerHTML=`${!navigator.onLine?'<div class="offline">Sin conexión. Reconectate para corregir ejercicios y guardar avances.</div>':''}<div class="shell"><aside class="sidebar"><a href="#home" class="brand"><img src="/icon.svg" alt="">impulso<span style="color:#ff9b32">.</span></a><nav>${nav('home','Mi aprendizaje','▤')}${nav('routes','Explorar rutas','◇')}${nav('progress','Mi progreso','↗')}${nav('institution','Institución','▦')}</nav><div class="sidebar-foot"><div class="pilot">PILOTO · VERSIÓN 0.1</div><p class="small muted">Un paso más cerca<br>de tu próximo desafío.</p>${user?'<button class="btn text" data-action="logout">Cerrar sesión</button>':'<button class="btn secondary" data-action="register">Guardar mi progreso</button>'}</div></aside><div class="workspace"><header class="topbar"><span class="crumb">${innerWidth<651?'impulso.':'Tu espacio para aprender'}</span><div class="account"><span class="pill orange">${completed()*50} XP</span>${user?`<button class="avatar" data-action="account" aria-label="Ver cuenta">${esc(user.name[0].toUpperCase())}</button>`:'<button class="btn outline" data-action="login">Ingresar</button>'}</div></header><main class="content fade">${content}</main></div></div>`}
function heading(title,subtitle){return `<div class="greeting"><div><h1>${title}</h1><p class="muted">${subtitle}</p></div><span class="pill">A tu ritmo · Sin presión</span></div>`}
function home(){const n=nextLesson(),done=completed();frame(`${heading(user?'Hola, '+esc(user.name.split(' ')[0])+' 👋':'Tu próximo paso empieza acá.','Unos minutos de práctica. Una habilidad que te llevás.')}<div class="layout"><div><section class="hero"><div class="hero-copy"><span class="eyebrow">ATENCIÓN AL CLIENTE · ${n.minutes} MIN</span><h2>${done===4?'Seguí practicando.':n.title+'.'}</h2><p>Practicá situaciones reales<br>con Laura, tu mentora.</p><button class="btn white" data-start="${n.id}">${done?'Continuar mi ruta':'Empezar mi primera misión'} <span aria-hidden="true">→</span></button></div><img src="/assets/mentor.webp" alt="Laura, mentora de atención al cliente"></section><div class="section-head"><h2>Tu camino de aprendizaje</h2><a href="#routes">Ver rutas</a></div><section class="path"><div class="path-head"><span class="small"><strong>01</strong> · Atención que genera confianza</span><span class="small muted">${done}/4</span></div>${catalog.lessons.map((l,i)=>{const finished=score(l.id)>=50,locked=i>0&&!(score(catalog.lessons[i-1].id)>=50);return `<div class="mission ${finished?'complete':locked?'':'current'}"><div class="step">${finished?'✓':i+1}</div><div class="mission-main"><h3>${l.title}</h3><p>${l.skill} · ${l.minutes} min</p></div><button class="btn ${finished?'secondary':locked?'outline':''}" data-start="${l.id}" ${locked?'disabled':''}>${finished?'Repetir':locked?'Pendiente':'Empezar'}</button></div>`}).join('')}</section></div><aside class="aside"><section class="card"><div class="goal-top"><h3>Tu ruta, paso a paso</h3><span aria-hidden="true">⚑</span></div><div class="goal-num">${done}<span> / 4 misiones</span></div><p class="small muted">${done===4?'¡Completaste la ruta piloto!':'Cada práctica cuenta.'}</p><div style="margin-top:19px"><progress max="4" value="${done}" aria-label="Misiones completadas"></progress></div><div class="week">${['L','M','M','J','V','S','D'].map((d,i)=>`<span class="day ${i===(new Date().getDay()+6)%7?'today':''}">${d}<b>${i===(new Date().getDay()+6)%7?'•':'·'}</b></span>`).join('')}</div></section><section class="card tip-card"><span class="pill">CONSEJO DE LAURA</span><h3>No necesitás saberlo todo.</h3><p>Escuchar, hacer una buena pregunta y confirmar lo entendido ya es un gran comienzo.</p></section>${!user?'<section class="card"><h3>Llevate tu progreso</h3><p class="small muted" style="margin:10px 0 16px">Probá sin registrarte. Con una cuenta podés continuar desde otro dispositivo.</p><button class="btn secondary" data-action="register">Tengo una invitación</button></section>':''}</aside></div>`)}
function routes(){frame(`${heading('Elegí tu próximo desafío.','Habilidades para trabajar, comunicarte y crecer.')}<div class="route-grid">${catalog.routes.map(r=>`<article class="route-card"><div style="display:flex;justify-content:space-between;align-items:center"><span class="route-icon ${r.color}">${r.symbol}</span><span class="pill ${r.available?'':'orange'}">${r.tag}</span></div><h2>${r.title}</h2><p>${r.subtitle}</p><div class="route-bottom"><span class="small muted">${r.available?'4 misiones · Nivel inicial':'Próximamente'}</span>${r.available?'<a href="#home" class="btn">Ir a mi ruta →</a>':'<span class="small muted">Todavía no disponible</span>'}</div></article>`).join('')}</div>`)}
function progressView(){const avg=progress.length?Math.round(progress.reduce((s,p)=>s+p.score,0)/progress.length):0;frame(`${heading('Mirá cuánto avanzaste.','Tu progreso se construye con práctica.')} ${!user?'<div class="notice">Modo de prueba: el avance se guarda únicamente en este navegador. No se comparte con ninguna institución.</div>':''}<div class="stats"><div class="card stat"><p>Misiones completadas</p><strong>${completed()} / 4</strong><p>Atención al cliente</p></div><div class="card stat"><p>Experiencia acumulada</p><strong>${completed()*50} XP</strong><p>50 XP por misión, sin duplicar repeticiones</p></div><div class="card stat"><p>Mejor resultado promedio</p><strong>${avg}%</strong><p>Sobre ejercicios realizados</p></div></div><section class="card"><h2 style="margin-bottom:25px">Habilidades practicadas</h2><div class="skills">${catalog.lessons.map(l=>`<div><div class="skill-top"><span>${l.skill}</span><span class="muted small">${score(l.id)===undefined?'Sin practicar':score(l.id)+'%'}</span></div><progress max="100" value="${score(l.id)||0}" aria-label="${l.skill}"></progress></div>`).join('')}</div><p class="small muted" style="margin-top:25px">Estos resultados corresponden a ejercicios del piloto. No constituyen una certificación de competencia laboral.</p></section>`)}
async function institution(){if(user?.role!=='admin'){frame(`${heading('El aprendizaje, en perspectiva.','Un espacio para acompañar a tu institución.')}<section class="card empty"><span class="route-icon" style="margin:0 auto 20px">▦</span><h2>Acceso institucional</h2><p class="muted">Consultá participantes, progreso y resultados reales<br>con tu cuenta de coordinación.</p><button class="btn" data-action="login">Ingresar a mi cuenta</button><p class="small muted" style="margin-top:18px">No mostramos datos de otros alumnos en el modo de prueba.</p></section>`);return}frame('<p class="loading">Cargando resultados…</p>');try{const{students}=await api('/api/institution');if(view!=='institution')return;const active=students.filter(s=>s.attempted>0),finished=students.filter(s=>s.completed===4);frame(`${heading(esc(catalog.institution),'Seguimiento de la cohorte piloto · Atención al cliente')}<div class="stats"><div class="card stat"><p>Participantes inscritos</p><strong>${students.length}</strong><p>Cuentas de alumnos</p></div><div class="card stat"><p>Comenzaron a practicar</p><strong>${active.length}</strong><p>Al menos una misión intentada</p></div><div class="card stat"><p>Completaron la ruta</p><strong>${finished.length}</strong><p>4 misiones aprobadas</p></div></div><div class="section-head"><h2>Participantes</h2><button id="export" class="btn outline">Exportar CSV</button></div><section class="card table-wrap">${students.length?`<table><thead><tr><th>Alumno</th><th>Misiones</th><th>Mejor promedio</th><th>Última práctica (UTC)</th></tr></thead><tbody>${students.map(s=>`<tr><td><strong>${esc(s.name)}</strong><br><span class="small muted">${esc(s.email)}</span></td><td>${s.completed||0}/4</td><td>${s.score===null?'—':s.score+'%'}</td><td>${esc(s.lastActive||'Sin actividad')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h3>Todavía no hay alumnos inscritos.</h3><p class="muted">Compartí el código de alumno de esta institución para comenzar.</p></div>'}</section><p class="small muted" style="margin-top:18px">Los promedios reflejan el mejor intento de cada misión. La devolución de IA no determina estas notas.</p>`);$('#export').onclick=()=>{const cell=v=>`"${String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')}"`;const rows=[['Nombre','Email','Completadas','Promedio','Ultima practica UTC'],...students.map(s=>[s.name,s.email,s.completed||0,s.score,s.lastActive])];const u=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='impulso-cohorte.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}}catch(e){toast(e.message);frame('<div class="empty">No pudimos cargar las métricas. <a href="#home">Volver al inicio</a></div>')}}
function lessonStart(id){const l=catalog.lessons.find(l=>l.id===id);if(!l)return;const i=catalog.lessons.indexOf(l);if(i>0&&!(score(catalog.lessons[i-1].id)>=50)){toast('Completá la misión anterior.');return}practice={lesson:l,stage:0,answers:[],selected:null,result:null};view='lesson';lessonRender()}
function lessonRender(){const p=practice,l=p.lesson,q=l.questions[p.stage-1];let body='';
 if(p.stage===0)body=`<span class="eyebrow muted">MISIÓN ${catalog.lessons.indexOf(l)+1} · ${l.minutes} MIN</span><h1>${l.title}</h1><video controls playsinline preload="metadata" poster="/assets/mentor.webp" aria-label="Presentación de Laura"><source src="/assets/intro.mp4" type="video/mp4"><track default kind="captions" src="/assets/intro.vtt" srclang="es" label="Español"></video><p class="small muted" style="margin-top:8px">Introducción visual con subtítulos · 15 segundos</p><div class="scene"><span class="eyebrow muted">LA SITUACIÓN</span><p style="margin-top:8px">${esc(l.scene)}</p></div><p>${esc(l.tip)}</p><div class="lesson-footer"><span class="small muted">Podés equivocarte y volver a probar.</span><button id="next" class="btn">Vamos a practicar →</button></div>`;
 else if(q)body=`<span class="eyebrow muted">ELEGÍ UNA RESPUESTA · ${p.stage}/${l.questions.length}</span><h1>${esc(q.prompt)}</h1><p class="muted">${esc(l.scene)}</p><div class="options">${q.options.map((o,i)=>`<button class="option ${p.selected===i?'selected':''}" data-option="${i}" aria-pressed="${p.selected===i}"><b>${String.fromCharCode(65+i)}</b>${esc(o)}</button>`).join('')}</div><div class="lesson-footer"><span class="small muted">Una buena respuesta hace la diferencia.</span><button id="next" class="btn" ${p.selected===null?'disabled':''}>${p.stage===l.questions.length?'Ver resultado':'Continuar →'}</button></div>`;
 else if(p.result)body=`<span class="eyebrow muted">MISIÓN ${p.result.score>=50?'COMPLETADA':'PARA VOLVER A PRACTICAR'}</span><h1>${p.result.score===100?'¡Muy bien resuelto!':p.result.score>=50?'Un paso más.':'Probemos una vez más.'}</h1><div class="result-number">${p.result.score}%</div><p class="muted">${p.result.score>=50?'Podés avanzar o seguir practicando.':'Revisá las explicaciones y repetí la misión para avanzar.'}</p>${p.result.results.map((r,i)=>`<div class="feedback ${r.correct?'':'retry'}"><strong>${r.correct?'✓':'↻'} Pregunta ${i+1}</strong><p>${esc(r.why)}</p></div>`).join('')}<div class="section-head"><h2>Ahora, con tus palabras</h2></div><p>${esc(l.practice)}</p><label for="answer" class="small muted">Usá un ejemplo ficticio, sin datos personales.</label><textarea id="answer" maxlength="2000" placeholder="Escribí cómo responderías…"></textarea><button id="coach" class="btn secondary" style="margin-top:12px" ${!catalog.aiEnabled?'disabled':''}>Recibir devolución de IA</button>${!catalog.aiEnabled?'<p class="small muted" style="margin-top:9px">Tutor IA pendiente de habilitación. Las misiones guiadas ya están disponibles.</p>':!user?'<p class="small muted">Ingresá con tu invitación para usar el tutor.</p>':''}<div id="coach-reply" role="status" aria-live="polite"></div><div class="lesson-footer"><button class="btn outline" data-start="${l.id}">Repetir misión</button><button id="finish" class="btn">Volver a mi camino →</button></div>`;
 frame(`<div class="lesson-wrap"><div class="lesson-top"><button id="exit" class="btn text" aria-label="Salir de la misión">✕</button><progress max="${l.questions.length+1}" value="${p.stage}" aria-label="Progreso de la misión"></progress><span class="small muted">${l.skill}</span></div><section class="lesson-card">${body}</section></div>`);
 $('#exit').onclick=()=>{view='home';home()};if($('#finish'))$('#finish').onclick=()=>{view='home';home()};
 document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{p.selected=Number(b.dataset.option);lessonRender()});
 if($('#next'))$('#next').onclick=async()=>{if(p.stage===0){p.stage=1;lessonRender();return}p.answers[p.stage-1]=p.selected;if(p.stage===l.questions.length){$('#next').disabled=true;$('#next').textContent='Revisando…';try{p.result=await api('/api/grade',{lesson:l.id,answers:p.answers});if(user){const me=await api('/api/me');progress=me.progress}else{const old=progress.find(x=>x.lesson===l.id);if(old){old.score=Math.max(old.score,p.result.score);old.attempts=(old.attempts||1)+1}else progress.push({lesson:l.id,score:p.result.score,attempts:1});try{localStorage.setItem('impulso-progress',JSON.stringify(progress))}catch{toast('Este navegador no permite guardar el avance.')}}p.stage++;p.selected=null;lessonRender()}catch(e){toast(e.message);lessonRender()}}else{p.stage++;p.selected=null;lessonRender()}};
 if($('#coach'))$('#coach').onclick=async()=>{if(!user){auth('login');return}const button=$('#coach');button.disabled=true;button.textContent='Preparando devolución…';try{const r=await api('/api/coach',{lesson:l.id,answer:$('#answer').value});$('#coach-reply').className='coach-result';$('#coach-reply').textContent=r.reply}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='Recibir devolución de IA'}};
}
function auth(mode='login'){const reg=mode==='register';dialog.innerHTML=`<div class="form-header"><h2>${reg?'Tu próximo paso':'Qué bueno verte'}</h2><button class="btn text" id="close-dialog" aria-label="Cerrar">✕</button></div><p class="muted small" style="margin-bottom:20px">${reg?'Usá la invitación de tu institución para guardar tus avances.':'Ingresá para continuar tu aprendizaje.'}</p><form class="form">${reg?'<label>Nombre<input name="name" autocomplete="name" required maxlength="60"></label>':''}<label>Email<input name="email" type="email" autocomplete="email" required maxlength="160"></label><label>Contraseña<input name="password" type="password" autocomplete="${reg?'new-password':'current-password'}" minlength="10" maxlength="128" required></label>${reg?'<label>Código de invitación<input name="code" required maxlength="200" autocomplete="off"></label><p class="small muted">Tu institución podrá ver tu nombre, email y resultados. El progreso de prueba no se transfiere a la cuenta.</p>':''}<p class="error" role="alert"></p><button class="btn" type="submit">${reg?'Crear mi cuenta':'Ingresar'}</button><button type="button" class="btn text" id="switch-auth">${reg?'Ya tengo cuenta':'Tengo una invitación'}</button></form>`;if(!dialog.open)dialog.showModal();$('#close-dialog').onclick=()=>dialog.close();$('#switch-auth').onclick=()=>auth(reg?'login':'register');dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=dialog.querySelector('[type=submit]');button.disabled=true;const data=Object.fromEntries(new FormData(e.target));try{const r=await api(reg?'/api/register':'/api/login',data);user=r.user;const me=await api('/api/me');progress=me.progress;dialog.close();if(view==='lesson')lessonRender();else render();toast('Tu sesión está lista.')}catch(err){dialog.querySelector('.error').textContent=err.message}finally{button.disabled=false}}}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-start],[data-action]');if(!b)return;if(b.dataset.start){lessonStart(b.dataset.start);return}const a=b.dataset.action;if(a==='login'||a==='register')auth(a);if(a==='logout'||a==='account'){if(a==='account'){dialog.innerHTML=`<div class="form-header"><h2>Tu cuenta</h2><button class="btn text" id="close-dialog">Cerrar</button></div><p>${esc(user.name)}</p><p class="muted">${esc(user.email)}</p><button class="btn outline" id="logout" style="margin-top:20px">Cerrar sesión</button>`;dialog.showModal();$('#close-dialog').onclick=()=>dialog.close();$('#logout').onclick=logout}else logout()}});
async function logout(){try{await api('/api/logout',{});user=null;progress=local();dialog.close();view='home';location.hash='home';home()}catch(e){toast(e.message)}}
function render(){if(view==='routes')routes();else if(view==='progress')progressView();else if(view==='institution')institution();else home()}
addEventListener('hashchange',()=>{view=location.hash.slice(1)||'home';practice=null;render();scrollTo(0,0)});
addEventListener('offline',()=>toast('Sin conexión. Los ejercicios necesitan conexión para guardar el resultado.'));addEventListener('online',()=>toast('Conexión restablecida.'));
async function init(){try{catalog=await api('/api/catalog');const me=await api('/api/me');user=me.user;progress=user?me.progress:local();view=location.hash.slice(1)||'home';render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}catch(e){app.innerHTML='<main class="content empty"><h1>No pudimos conectar.</h1><p class="muted">Revisá tu conexión y volvé a intentar.</p><button id="retry" class="btn" style="margin-top:20px">Reintentar</button></main>';$('#retry').onclick=init}}
init();
